interface Props { definition: CalculatorDefinition; patient?: Patient; onBack: () => void; }
const Toggle:React.FC<{label:string;value:boolean;onChange:(v:boolean)=>void}>=({label,value,onChange})=><label className="flex items-center gap-3 p-3 rounded-xl bg-slate-50 dark:bg-slate-900/70 border border-slate-200 dark:border-slate-800 text-sm cursor-pointer"><input type="checkbox" checked={value} onChange={e=>onChange(e.target.checked)} className="w-4 h-4 accent-cyan-500"/><span>{label}</span></label>;
const Num:React.FC<{label:string;value:number;onChange:(n:number)=>void;step?:string;min?:string;max?:string}>=({label,value,onChange,step='any',min,max})=><label className="text-xs font-semibold text-slate-600 dark:text-slate-300">{label}<input type="number" step={step} min={min} max={max} value={Number.isFinite(value)?value:''} onChange={e=>onChange(Number(e.target.value))} className="w-full mt-1 px-3 py-2.5 rounded-xl bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-700 text-sm text-slate-900 dark:text-white"/></label>;
const Select:React.FC<{label:string;value:string|number;onChange:(v:string)=>void;options:Array<[string,string]>}>=({label,value,onChange,options})=><label className="text-xs font-semibold text-slate-600 dark:text-slate-300">{label}<select value={value} onChange={e=>onChange(e.target.value)} className="w-full mt-1 px-3 py-2.5 rounded-xl bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-700 text-sm text-slate-900 dark:text-white">{options.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label>;
const Result:React.FC<{title?:string;children:React.ReactNode}>=({title='Result',children})=><div className="mt-5 p-4 rounded-2xl bg-cyan-500/10 border border-cyan-500/30 text-slate-700 dark:text-slate-200"><div className="text-[10px] uppercase tracking-wider font-bold text-cyan-600 dark:text-cyan-400 mb-2">{title}</div>{children}</div>;
const Grid:React.FC<{children:React.ReactNode}>=({children})=><div className="grid sm:grid-cols-2 gap-3">{children}</div>;

