 const [curb,setCurb]=useState(Array(5).fill(false)),[orbit,setOrbit]=useState(Array(5).fill(false)),[crusadeFemale,setCrusadeFemale]=useState(false),[crusadeDm,setCrusadeDm]=useState(false),[crusadeVasc,setCrusadeVasc]=useState(false),[crusadeChf,setCrusadeChf]=useState(false),[crusadeHr,setCrusadeHr]=useState(latest?.hr||80),[crusadeSbp,setCrusadeSbp]=useState(latest?.sbp||120),[crusadeHct,setCrusadeHct]=useState(40),[crusadeCr,setCrusadeCr]=useState(90);
