 const [heartHistory,setHeartHistory]=useState('0'),[heartEcg,setHeartEcg]=useState('0'),[heartAge,setHeartAge]=useState(age>=65?'2':age>=45?'1':'0'),[heartRisk,setHeartRisk]=useState('0'),[heartTroponin,setHeartTroponin]=useState('0');
 const [timiAge,setTimiAge]=useState(false),[timiCad,setTimiCad]=useState(false),[timiKnown,setTimiKnown]=useState(false),[timiAspirin,setTimiAspirin]=useState(false),[timiAngina,setTimiAngina]=useState(false),[timiMarkers,setTimiMarkers]=useState(false),[timiSt,setTimiSt]=useState(false);
