 const [newsRR,setNewsRR]=useState(latest?.rr||18),[newsSpo2,setNewsSpo2]=useState(latest?.spo2||98),[newsO2,setNewsO2]=useState(false),[newsSBP,setNewsSBP]=useState(latest?.sbp||120),[newsPulse,setNewsPulse]=useState(latest?.hr||75),[newsConscious,setNewsConscious]=useState('Alert'),[newsTemp,setNewsTemp]=useState(latest?.temp||37);
 const [gcsE,setGcsE]=useState('4'),[gcsV,setGcsV]=useState('5'),[gcsM,setGcsM]=useState('6');
