 const [sbp,setSbp]=useState(latest?.sbp||120),[dbp,setDbp]=useState(latest?.dbp||70),[mapHr,setMapHr]=useState(latest?.hr||75),[cvp,setCvp]=useState(5),[height,setHeight]=useState(170),[weight,setWeight]=useState(70),[co,setCo]=useState(5);
 const [infWeight,setInfWeight]=useState(weight),[drugMg,setDrugMg]=useState(4),[diluent,setDiluent]=useState(250),[targetDose,setTargetDose]=useState(0.1),[rate,setRate]=useState(10),[infDirection,setInfDirection]=useState('doseToRate');
 const [crAge,setCrAge]=useState(age),[crWeight,setCrWeight]=useState(weight),[cr,setCr]=useState(1),[crSex,setCrSex]=useState(sex);
