 const [abgPh,setAbgPh]=useState(7.4),[abgPco2,setAbgPco2]=useState(40),[abgHco3,setAbgHco3]=useState(24),[abgNa,setAbgNa]=useState(140),[abgCl,setAbgCl]=useState(104),[abgAlb,setAbgAlb]=useState(4),[abgPao2,setAbgPao2]=useState(90),[abgFio2,setAbgFio2]=useState(21);
 const cha=MedicalCalculators.calcCHA2DS2VASc({chf:chaChf,htn:chaHtn,age75Plus:chaAge>=75,diabetes:chaDiabetes,strokeOrTia:chaStroke,vascularDisease:chaVascular,age65To74:chaAge>=65&&chaAge<75,isFemale:chaSex==='Female'});
