   const pf=sofaFio2>0?sofaPao2/(sofaFio2/100):0; let r=pf>=400?0:pf>=300?1:pf>=200?2:pf>=100?3:4; if(r>=3&&!sofaSupport) r=2;
   const c=sofaPlt>=150?0:sofaPlt>=100?1:sofaPlt>=50?2:sofaPlt>=20?3:4;
