 const corr=MedicalCalculators.calcElectrolyteCorrections(na,glucose,ca,albumin); const fena=MedicalCalculators.calcFENa(uNa,sNa,uCr,sCr); const fw=MedicalCalculators.calcFreeWaterDeficit(sNa,fwWeight,fwSex as 'Male'|'Female');
