 const grace=MedicalCalculators.calcGRACE({age:graceAge,hr:graceHr,sbp:graceSbp,creatinine:graceCr,killip:graceKillip,cardiacArrest:graceArrest,stDeviation:graceSt,elevatedMarkers:graceMarkers});
